import {cityLibrary,cityRecord,CITY_LIMIT} from './city-library.js?v=original-music-1';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sequence=0;
export async function showCityLibrary({city,dialog,close,restore,validate,download,notify,isCurrent}){
 const token=++sequence,title='Saved city library',again=()=>showCityLibrary({city,dialog,close,restore,validate,download,notify,isCurrent});
 dialog(title,'<p role="status">Opening your saved cities…</p>');
 let entries;try{entries=await cityLibrary.list();}catch(e){if(isCurrent(title))dialog(title,`<p role="alert">${escape(e.message)}</p>`);return;}
 if(token!==sequence||!isCurrent(title))return;
 dialog(title,`<p>Keep up to ${CITY_LIMIT} named cities in this browser. These are independent snapshots; Save city and autosave keep their separate slots. Download city files for a portable copy. Clearing browser site data removes this library.</p><label>New save name<input id="libraryName" maxlength="60" value="${escape(city().name)}"></label><button id="librarySave" class="primary" ${entries.length>=CITY_LIMIT?'disabled':''}>Save current city as a new entry</button><p id="libraryStatus" role="status">${entries.length} / ${CITY_LIMIT} cities saved</p>${entries.length?entries.map(e=>`<article class="milestone"><h3>${escape(e.label)}</h3><p>${escape(e.name)} · ${e.size||48} × ${e.size||48} tiles · ${Math.floor(e.month/12)+e.startYear} · ${Math.round(e.population).toLocaleString()} residents · §${Math.round(e.funds).toLocaleString()}</p><small>Saved ${escape(new Date(e.savedAt).toLocaleString())}</small><div class="actions"><button data-library-load="${escape(e.id)}">Load</button><button data-library-export="${escape(e.id)}">Download</button><button data-library-rename="${escape(e.id)}">Rename</button><button data-library-replace="${escape(e.id)}">Replace with current city</button><button data-library-delete="${escape(e.id)}">Delete</button></div></article>`).join(''):'<p>No named cities yet. Save this city above before starting another.</p>'}`);
 const status=message=>{if(isCurrent(title))document.querySelector('#libraryStatus').textContent=message;},run=async action=>{try{await action();}catch(e){if(isCurrent(title))status(e.message);else notify(e.message);}};
 document.querySelector('#librarySave').onclick=e=>{e.target.disabled=true;const label=document.querySelector('#libraryName').value;run(async()=>{try{await cityLibrary.save('city:'+crypto.randomUUID(),cityRecord(city(),label));if(isCurrent(title))await again();}finally{if(e.target.isConnected)e.target.disabled=false;}});};
 document.querySelectorAll('[data-library-export]').forEach(b=>b.onclick=()=>run(async()=>{const r=await cityLibrary.load(b.dataset.libraryExport);if(!r)throw Error('This saved city no longer exists.');download('sims3000-city.json',r.raw);}));
 document.querySelectorAll('[data-library-load]').forEach(b=>b.onclick=()=>run(async()=>{const r=await cityLibrary.load(b.dataset.libraryLoad);if(!r)throw Error('This saved city no longer exists.');const loaded=validate(JSON.parse(r.raw));if(!isCurrent(title))return;dialog('Load library city?',`<p>Replace the current city with <strong>${escape(r.label)}</strong>? The loaded city will be paused. Save or download current progress first if needed.</p><div class="actions"><button id="libraryKeep">Download current city</button><button id="libraryConfirm" class="primary">Load city</button><button id="libraryBack">Back</button></div>`);document.querySelector('#libraryKeep').onclick=()=>download('sims3000-city.json',cityRecord(city()).raw);document.querySelector('#libraryBack').onclick=again;document.querySelector('#libraryConfirm').onclick=()=>{restore(loaded);close();notify('Library city restored and paused.');};}));
 for(const action of ['rename','replace','delete'])document.querySelectorAll(`[data-library-${action}]`).forEach(b=>b.onclick=()=>{const id=b.dataset['library'+action[0].toUpperCase()+action.slice(1)],entry=entries.find(e=>e.id===id);dialog(action==='rename'?'Rename saved city':action==='replace'?'Replace saved city?':'Delete saved city?',`<p>${action==='delete'?'Delete only the stored snapshot':action==='replace'?'Replace this snapshot with the current city':'Change the library label'}: <strong>${escape(entry.label)}</strong>.</p>${action==='rename'?`<label>Name<input id="libraryRename" maxlength="60" value="${escape(entry.label)}"></label>`:''}<p id="libraryActionError" role="alert"></p><div class="actions"><button id="libraryActionConfirm">${action==='rename'?'Rename':action==='replace'?'Replace':'Delete'}</button><button id="libraryBack">Back</button></div>`);document.querySelector('#libraryBack').onclick=again;document.querySelector('#libraryActionConfirm').onclick=async e=>{e.target.disabled=true;try{if(action==='rename')await cityLibrary.rename(id,document.querySelector('#libraryRename').value);else if(action==='delete')await cityLibrary.remove(id);else await cityLibrary.save(id,cityRecord(city(),entry.label));if(e.target.isConnected)await again();}catch(error){if(e.target.isConnected){document.querySelector('#libraryActionError').textContent=error.message;e.target.disabled=false;}}};});
}
